import{_ as d,o as e,c as r,a4 as i}from"./chunks/framework.BMj-uaUw.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"前端工程化开发","text":"从工程地基到项目上线","tagline":"用一个校园活动服务平台贯穿 12 个单元 —— 管理端做 Web，用户端做手机。教程里的示例可以直接在页面上运行，代码可以直接抄进你的项目。","actions":[{"theme":"brand","text":"从课程导学开始","link":"/guide/"},{"theme":"alt","text":"直奔 12 个单元","link":"/unit01/"},{"theme":"alt","text":"综合项目设计","link":"/project/"}]},"features":[{"icon":"🧱","title":"先讲清问题，再给工具","details":"每个知识点都从\\"不这么做会出什么事\\"讲起。工程化不是工具清单，是解决具体麻烦的手段。"},{"icon":"▶️","title":"示例看得见、点得动","details":"关键示例做成了页面上可交互的组件，切换标签就能看效果与源码，不用先配环境再猜结果。"},{"icon":"🎯","title":"一条主线贯穿始终","details":"校园活动服务平台从第 3 周建仓库开始，所有练习都在同一个工程里做，最后两周只做收口。"},{"icon":"📱","title":"管理端之外还有用户端","details":"项目有第二个端 —— 学生用手机报名。用 uni-app 一套代码编译到 H5 与微信小程序，从建工程、写页面到打包发布都是完整一条线。"},{"icon":"🧭","title":"四态、规范、异常处理","details":"加载中、出错、空数据、有数据——这类\\"上课不考、上班天天用\\"的细节，教程里当作硬要求写。"},{"icon":"🛠","title":"版本全部核对过","details":"文中的依赖版本均按 npm 仓库现状核对，不写记不准的版本号；教学统一用稳定版。"},{"icon":"📋","title":"每章都有练习","details":"练习给思路不给答案，另配常见坑与排查清单，方便自查和互评。"},{"icon":"🤝","title":"AI 协作作为并行主线","details":"每个单元配一节 AI 协作，讲这一章哪些活能交给 AI、提示词怎么写、AI 在这里容易错什么、怎么验收。工具以国内可直接使用的为主。"}]},"headers":[{"level":2,"title":"这套教程怎么用","slug":"这套教程怎么用","link":"#这套教程怎么用","children":[]},{"level":2,"title":"离线版下载","slug":"离线版下载","link":"#离线版下载","children":[]},{"level":2,"title":"12 个单元一览","slug":"_12-个单元一览","link":"#_12-个单元一览","children":[]},{"level":2,"title":"用户端：同一套后端的第二个端","slug":"用户端-同一套后端的第二个端","link":"#用户端-同一套后端的第二个端","children":[]},{"level":2,"title":"AI 协作：一条并行主线","slug":"ai-协作-一条并行主线","link":"#ai-协作-一条并行主线","children":[]},{"level":2,"title":"综合项目：校园活动服务平台","slug":"综合项目-校园活动服务平台","link":"#综合项目-校园活动服务平台","children":[]},{"level":2,"title":"课程用到的技术","slug":"课程用到的技术","link":"#课程用到的技术","children":[]}],"relativePath":"index.md","filePath":"index.md","lastUpdated":1789500889000}'),a={name:"index.md"};function l(n,t,o,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h2 id="这套教程怎么用" tabindex="-1">这套教程怎么用 <a class="header-anchor" href="#这套教程怎么用" aria-label="Permalink to &quot;这套教程怎么用&quot;">​</a></h2><p>这份教程是《前端工程化开发》48 学时的配套材料，按 <strong>12 周 × 4 学时</strong> 组织成 12 个单元， 每个单元正好一次课。教程本身可以独立自学，也可以作为课堂实训的操作手册。</p><div class="tip custom-block"><p class="custom-block-title">三种读法</p><ul><li><strong>课前预习</strong>：先读本单元的“单元导学”和知识点小节，把示例跑一遍，带着问题进课堂。</li><li><strong>课中动手</strong>：直接翻到本单元对应的案例与练习，把实训任务做完。</li><li><strong>课后复习</strong>：看“常见坑”和“课后练习”自测，答不上来的地方再回到正文。</li></ul></div><h2 id="离线版下载" tabindex="-1">离线版下载 <a class="header-anchor" href="#离线版下载" aria-label="Permalink to &quot;离线版下载&quot;">​</a></h2><p>机房网络不稳、想把整本存到本地慢慢看，可以下载单文件版：全部内容打成一个 HTML 文件， 双击就能打开，不需要联网，也不需要装 Node。</p><p><a href="./download/%E5%89%8D%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%BC%80%E5%8F%91-%E5%AE%8C%E6%95%B4%E6%95%99%E7%A8%8B.html" download="前端工程化开发-完整教程.html">下载离线版（约 3.9 MB）</a></p><p>下载后建议用浏览器的“另存为”保留一份，方便断网和考试周复习时翻看。</p><h2 id="_12-个单元一览" tabindex="-1">12 个单元一览 <a class="header-anchor" href="#_12-个单元一览" aria-label="Permalink to &quot;12 个单元一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>单元</th><th>主题</th><th>学时</th><th>周次</th></tr></thead><tbody><tr><td>一 · 工程化认知与工具链</td><td>1</td><td>工程化认知、学习路线与开发环境</td><td>4</td><td>第 1 周</td></tr><tr><td></td><td>2</td><td>Node.js 生态、包管理与构建工具</td><td>4</td><td>第 2 周</td></tr><tr><td></td><td>3</td><td>工程规范、质量保障与 Git 协作</td><td>4</td><td>第 3 周</td></tr><tr><td>二 · Vue 3 核心基础</td><td>4</td><td>模板语法与响应式基础</td><td>4</td><td>第 4 周</td></tr><tr><td></td><td>5</td><td>计算属性、侦听器与渲染控制</td><td>4</td><td>第 5 周</td></tr><tr><td></td><td>6</td><td>用户交互与表单绑定</td><td>4</td><td>第 6 周</td></tr><tr><td>三 · 组件化开发</td><td>7</td><td>组件基础与父子通信</td><td>4</td><td>第 7 周</td></tr><tr><td></td><td>8</td><td>组件进阶与逻辑复用</td><td>4</td><td>第 8 周</td></tr><tr><td>四 · 应用架构</td><td>9</td><td>路由与登录鉴权</td><td>4</td><td>第 9 周</td></tr><tr><td></td><td>10</td><td>Pinia 状态管理与数据请求层</td><td>4</td><td>第 10 周</td></tr><tr><td>五 · 综合项目实战</td><td>11</td><td>项目启动与核心业务实现</td><td>4</td><td>第 11 周</td></tr><tr><td></td><td>12</td><td>联调、优化、部署与答辩</td><td>4</td><td>第 12 周</td></tr></tbody></table><h2 id="用户端-同一套后端的第二个端" tabindex="-1">用户端：同一套后端的第二个端 <a class="header-anchor" href="#用户端-同一套后端的第二个端" aria-label="Permalink to &quot;用户端：同一套后端的第二个端&quot;">​</a></h2><p>12 个单元的主体是管理端（Web）。但学生不会为了报名去开电脑，所以项目还有第二个端 —— <strong>用手机报名的用户端</strong>，用 uni-app 写，一套代码编译到 H5 和微信小程序。</p><p>用户端不占用 12 周的教学结构，它是管理端跑通之后的延伸：管理端趟过一遍的请求封装、 四态页面、错误码分层，这里照着做，但手机端有自己的一堆坑 —— 跨端框架锁定的依赖版本、 rpx 单位、页面栈层数、没有全局路由守卫、组件库的包名迁移等等，都单独讲清楚。</p><p>单独开了一栏 11 篇，从&quot;为什么是 uni-app&quot;讲到&quot;打包发布&quot;。做完管理端再看这一栏， 或者作为课后的选做内容都行。</p><p><a href="/frontend-engineering-course/mobile/">进入用户端专栏</a></p><h2 id="ai-协作-一条并行主线" tabindex="-1">AI 协作：一条并行主线 <a class="header-anchor" href="#ai-协作-一条并行主线" aria-label="Permalink to &quot;AI 协作：一条并行主线&quot;">​</a></h2><p>48 学时的结构不变，AI 协作作为一条并行主线从第 1 周延续到第 12 周。它不额外占课时， 建议的用法是每个单元讲完后，课后花半小时用 AI 把当天的练习再做一遍，然后自己验一遍。</p><table tabindex="0"><thead><tr><th>位置</th><th>内容</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/guide/ai-coding.html">AI 编程：用之前先知道它的边界</a></td><td>工具现状、风险数据、本课程的三条约定</td></tr><tr><td>每个单元的“AI 协作”节</td><td>这一章哪些活能交给 AI、提示词怎么写、AI 容易错什么、怎么验收</td></tr><tr><td><a href="/frontend-engineering-course/project/ai-collaboration.html">综合项目 · AI 协作规范</a></td><td>AGENTS.md 完整模板、从规格到实现的流程、AI 参与声明、评审清单</td></tr><tr><td><a href="/frontend-engineering-course/appendix/ai-tools.html">AI 编程工具速查</a></td><td>工具对比、提示词句式库、AI 代码审查清单、核实命令</td></tr></tbody></table><h2 id="综合项目-校园活动服务平台" tabindex="-1">综合项目：校园活动服务平台 <a class="header-anchor" href="#综合项目-校园活动服务平台" aria-label="Permalink to &quot;综合项目：校园活动服务平台&quot;">​</a></h2><p>项目取“活动发布 → 报名审核 → 场次安排”这条主线。管理端规模控制在 12 周内能完成的范围： 3 个业务页面、1 个登录入口、1 个数据看板，两个角色（组织者、审核员）。</p><p>管理端跑通之后，再补一个用户端：学生用手机看活动、报名、查自己的报名记录。 5 个页面，用 uni-app 写，编译到 H5 和微信小程序。两端共用一套后端接口。</p><p>选这个场景的理由很直接 —— 你就是这个场景的用户，需求不需要解释，精力可以放在工程化本身； 而它天然带着状态流转、时段冲突、名额联动、角色权限、跨端适配这些能真正练手的点。</p><ul><li><a href="/frontend-engineering-course/project/">项目总览</a></li><li><a href="/frontend-engineering-course/project/requirements.html">管理端需求规格</a></li><li><a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a></li><li><a href="/frontend-engineering-course/project/rules.html">业务规则与状态流转</a></li><li><a href="/frontend-engineering-course/project/api.html">接口约定</a></li></ul><h2 id="课程用到的技术" tabindex="-1">课程用到的技术 <a class="header-anchor" href="#课程用到的技术" aria-label="Permalink to &quot;课程用到的技术&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>选型</th><th>说明</th></tr></thead><tbody><tr><td>运行时</td><td>Node.js 24 LTS</td><td>前端工具链的运行基础</td></tr><tr><td>包管理</td><td>pnpm</td><td>磁盘占用小、安装快，锁文件严格</td></tr><tr><td>构建</td><td>Vite</td><td>开发态按需编译，生产态打包</td></tr><tr><td>框架</td><td>Vue 3（组合式 API）</td><td>全程 <code>&lt;script setup&gt;</code>，不用选项式写法</td></tr><tr><td>路由</td><td>Vue Router 5</td><td>嵌套路由、懒加载、导航守卫</td></tr><tr><td>状态</td><td>Pinia 4</td><td>组合式写法，按业务模块拆分</td></tr><tr><td>请求</td><td>axios</td><td>实例封装 + 双拦截器</td></tr><tr><td>规范</td><td>ESLint + Prettier + Stylelint</td><td>编辑器联动 + 提交钩子双重拦截</td></tr><tr><td>管理端 UI</td><td>Element Plus 2</td><td>表格、表单、弹窗等后台常用组件</td></tr><tr><td>用户端跨端</td><td>uni-app（经典版）</td><td>一套代码编译到 H5 与微信小程序</td></tr><tr><td>用户端 UI</td><td>Wot UI（<code>@wot-ui/ui</code>）</td><td>手机端组件库，通过 easycom 按需引入</td></tr></tbody></table><p>两端用的构建工具版本不一样（uni-app 官方模板锁 Vite 5、Vue 3.4），这是跨端框架的固有代价， <a href="/frontend-engineering-course/mobile/">用户端总览</a>里有一张完整对照表。具体版本号见 <a href="/frontend-engineering-course/appendix/tools.html">工具链与版本清单</a>。</p>',25)])])}const g=d(a,[["render",l]]);export{u as __pageData,g as default};
